// XPact Engine - PCHBench Phase-0 .Build.cs. The benchmark target depends on
// the stub shared PCH header (large enough to be a meaningful test case once
// XCorePCH.h is fleshed out in Phase 1 Task 1.1). The .cpp files used by this
// target are generated by Scripts/Windows/Generate-PCHBench.ps1.

using XBT.Configuration.Rules;

public class PCHBench : ModuleRules
{
	public PCHBench(TargetRules target) : base(target)
	{
		Type = ModuleType.CPlusPlus;
		PCHUsage = PCHUsageMode.UseSharedPCHs;
		SharedPCHHeaderFile = "XCorePCH.Stub.h";
	}
}
